  function createElement([tag, attrs, children = []]) {
    const el = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [k, v] of Object.entries(attrs)) {
      el.setAttribute(k, v);
    }
    for (const child of children) {
      el.appendChild(createElement(child));
    }
    return el;
  }

  function createIcons(options = {}) {
    const attrs = Object.assign({
      xmlns: 'http://www.w3.org/2000/svg',
      width: 24,
      height: 24,
      viewBox: '0 0 24 24',
      fill: 'none',
      stroke: 'currentColor',
      'stroke-width': 2,
      'stroke-linecap': 'round',
      'stroke-linejoin': 'round'
    }, options.attrs || {});

    const elements = document.querySelectorAll('[data-lucide]');
    elements.forEach(element => {
      const name = element.getAttribute('data-lucide');
      const iconData = icons[name];
      if (!iconData) return;

      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      for (const [k, v] of Object.entries(attrs)) {
        svg.setAttribute(k, v);
      }
      
      // Copy classes and other attributes from original element
      if (element.className) {
        svg.setAttribute('class', 'lucide lucide-' + name + ' ' + element.className);
      } else {
        svg.setAttribute('class', 'lucide lucide-' + name);
      }
      
      const elWidth = element.getAttribute('width');
      if (elWidth) svg.setAttribute('width', elWidth);
      const elHeight = element.getAttribute('height');
      if (elHeight) svg.setAttribute('height', elHeight);

      // Icon data is [tag, attrs, children]
      // iconData[2] is children array
      if (Array.isArray(iconData[2])) {
        for (const child of iconData[2]) {
          svg.appendChild(createElement(child));
        }
      }

      element.parentNode.replaceChild(svg, element);
    });
  }

  root.lucide = {
    createIcons: createIcons,
    icons: icons
  };
